<script setup lang="ts">
import {ref,nextTick,onMounted} from 'vue'
import {saveDraft,listDrafts,deleteDraft} from './storage'
import {createId} from './id'
const serverStatus=ref('')
const themes=[{name:'山野来信',tag:'旅行',color:'#e7e9dd',ink:'#354638'},{name:'城市漫游',tag:'城市',color:'#eee6da',ink:'#725443'},{name:'日常有光',tag:'日常',color:'#f3e4de',ink:'#8a4d43'}]
const page=ref('home'),canvas=ref<HTMLCanvasElement>(),input=ref<HTMLInputElement>(),theme=ref(0),title=ref('把日子，过成风景'),note=ref('走过的路，看过的风景，都值得好好收藏。'),date=ref(new Date().toLocaleDateString('sv-SE')),photos=ref<string[]>([]),selected=ref(0),zoom=ref(1),offsetX=ref(0),offsetY=ref(0),fill=ref('cover'),status=ref(''),busy=ref(false),error=ref(''),drafts=ref<any[]>([]),output=ref(''),format=ref('image/jpeg'),stickers=ref<{text:string,x:number,y:number}[]>([])
let id=createId(),history:string[]=[],future:string[]=[],timer:ReturnType<typeof setTimeout>,generation=0
const crops=ref<any[]>([])
function snapshot(){return JSON.stringify({id,theme:theme.value,title:title.value,note:note.value,date:date.value,photos:photos.value,crops:crops.value,stickers:stickers.value})}
function restore(s:string){const d=JSON.parse(s);id=d.id;theme.value=d.theme;title.value=d.title;note.value=d.note;date.value=d.date;photos.value=d.photos;crops.value=d.crops||[];stickers.value=d.stickers||[];select(0)}
function checkpoint(){history.push(snapshot());if(history.length>50)history.shift();future=[]}
function undo(){if(!history.length)return;future.push(snapshot());restore(history.pop()!);changed()}
function redo(){if(!future.length)return;history.push(snapshot());restore(future.pop()!);changed()}
function select(i:number){selected.value=i;const c=crops.value[i]||{};zoom.value=c.zoom||1;offsetX.value=c.x||0;offsetY.value=c.y||0;fill.value=c.fill||'cover'}
function crop(){checkpoint();crops.value[selected.value]={zoom:zoom.value,x:offsetX.value,y:offsetY.value,fill:fill.value};changed()}
async function persist(){const current=snapshot();status.value='保存中';try{await saveDraft({...JSON.parse(current),updatedAt:Date.now()});status.value='已保存到此浏览器'}catch{status.value='本机保存失败，请及时保存图片'}}
function changed(){output.value='';void render();clearTimeout(timer);timer=setTimeout(persist,800)}
async function openEditor(t=theme.value){theme.value=t;page.value='editor';output.value='';await nextTick();await render()}
function editText(){changed()}
async function readFiles(e:Event){const files=Array.from((e.target as HTMLInputElement).files||[]);if(!files.length)return;if(files.length>6){error.value='一次最多选择 6 张照片，请重新选择';return}busy.value=true;error.value='';const ready:string[]=[];for(const f of files){try{if(f.size>20*1024*1024)throw Error('照片超过 20 MB');const url=URL.createObjectURL(f);try{const image=await load(url);if(image.width*image.height>50000000)throw Error('照片像素超过 5000 万');const s=Math.min(1,4096/Math.max(image.width,image.height));const c=document.createElement('canvas');c.width=Math.round(image.width*s);c.height=Math.round(image.height*s);c.getContext('2d')!.drawImage(image,0,0,c.width,c.height);ready.push(c.toDataURL('image/jpeg',.9));c.width=c.height=0}finally{URL.revokeObjectURL(url)}}catch{error.value='部分照片无法读取或超过限制；已保留其他有效照片。HEIC 请转换为 JPEG。'}}if(ready.length){checkpoint();photos.value=ready;crops.value=[];select(0);await openEditor();changed()}busy.value=false;(e.target as HTMLInputElement).value=''}
function load(src:string):Promise<HTMLImageElement>{return new Promise((resolve,reject)=>{const i=new Image();i.onload=()=>resolve(i);i.onerror=reject;i.src=src})}
function boxes(n:number){if(n<=1)return [{x:110,y:260,w:980,h:980}];if(n<=3)return [{x:90,y:250,w:1020,h:600},{x:90,y:885,w:490,h:420},{x:620,y:885,w:490,h:420}].slice(0,n);return Array.from({length:n},(_,i)=>({x:90+(i%2)*530,y:250+Math.floor(i/2)*350,w:490,h:320}))}
async function render(target=canvas.value){if(!target)return;const ticket=++generation;target.width=1200;target.height=1600;const ctx=target.getContext('2d')!;const t=themes[theme.value];ctx.fillStyle=t.color;ctx.fillRect(0,0,1200,1600);ctx.fillStyle=t.ink;ctx.font='20px sans-serif';ctx.fillText('TRAVEL DIARY  /  '+date.value,90,90);ctx.font='bold 56px sans-serif';ctx.fillText(title.value.slice(0,20),90,180,1020);const b=boxes(photos.value.length||3);for(let j=0;j<b.length;j++){const p=b[j];ctx.fillStyle='#fffdf8';ctx.fillRect(p.x-12,p.y-12,p.w+24,p.h+24);if(photos.value[j]){const im=await load(photos.value[j]);if(ticket!==generation)return;ctx.save();ctx.beginPath();ctx.rect(p.x,p.y,p.w,p.h);ctx.clip();const c=crops.value[j]||{};if(c.fill==='stretch')ctx.drawImage(im,p.x,p.y,p.w,p.h);else{const s=Math.max(p.w/im.width,p.h/im.height)*(c.zoom||1),w=im.width*s,h=im.height*s;ctx.drawImage(im,p.x+(p.w-w)/2+(c.x||0)*(w-p.w)/200,p.y+(p.h-h)/2+(c.y||0)*(h-p.h)/200,w,h)}ctx.restore()}else{ctx.fillStyle=['#b9c6b2','#d4bba2','#b5c5c8'][j%3];ctx.fillRect(p.x,p.y,p.w,p.h);ctx.fillStyle='#ffffffbb';ctx.font='32px sans-serif';ctx.fillText('点击选择你的照片',p.x+30,p.y+p.h/2)}}ctx.fillStyle=t.ink;ctx.font='26px sans-serif';const text=note.value;for(let i=0;i<Math.min(text.length,120);i+=36)ctx.fillText(text.slice(i,i+36),90,1400+Math.floor(i/36)*40);for(const st of stickers.value){ctx.font='72px sans-serif';ctx.fillText(st.text,st.x,st.y)}ctx.font='18px sans-serif';ctx.fillText('MEMORIES WORTH KEEPING',90,1540)}
function addSticker(text:string){checkpoint();stickers.value.push({text,x:900-(stickers.value.length%3)*100,y:200+stickers.value.length*90});changed()}
function closeOutput(){if(output.value)URL.revokeObjectURL(output.value);output.value=''}
async function exportImage(){busy.value=true;error.value='';try{if(!photos.value.length)throw Error('请先添加自己的照片');await document.fonts.ready;await render();const blob=await new Promise<Blob|null>(r=>canvas.value!.toBlob(r,format.value,.92));if(!blob)throw Error('图片生成失败');if(output.value)URL.revokeObjectURL(output.value);output.value=URL.createObjectURL(blob)}catch(e:any){error.value=e.message}finally{busy.value=false}}
async function showDrafts(){try{drafts.value=(await listDrafts()).sort((a:any,b:any)=>b.updatedAt-a.updatedAt);page.value='drafts'}catch{error.value='当前浏览器无法读取本机草稿'}}
async function resume(d:any){clearTimeout(timer);restore(JSON.stringify(d));history=[];future=[];await openEditor()}
async function remove(id:string){if(confirm('删除这份本机作品？')){await deleteDraft(id);await showDrafts()}}
function newWork(){clearTimeout(timer);void persist();id=createId();photos.value=[];crops.value=[];stickers.value=[];history=[];future=[];openEditor()}
onMounted(()=>{fetch('/api/public/v1/bootstrap/').then(r=>{if(!r.ok)throw Error();return r.json()}).then(()=>{serverStatus.value='服务端已连接'}).catch(()=>{serverStatus.value='本地模式：服务端暂不可用'});window.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key==='z'&&!(e.target instanceof HTMLInputElement||e.target instanceof HTMLTextAreaElement)){e.preventDefault();e.shiftKey?redo():undo()}})})
</script>
<template>
<header><a class="brand" href="#" @click.prevent="page='home'">◒ <span>TravelDiary</span></a><nav><button @click="page='templates'">探索模板</button><button @click="showDrafts">本机作品</button><button class="primary" @click="newWork">开始创作 ↗</button></nav></header>
<input ref="input" hidden type="file" accept="image/jpeg,image/png,image/webp,image/heic,image/heif" multiple @change="readFiles">
<div v-if="error" class="notice" role="alert">{{error}} <button @click="error=''">关闭</button></div>
<main v-if="page==='home'"><section class="hero"><div><div class="eyebrow">A LITTLE JOURNAL, A BEAUTIFUL MEMORY</div><h1>让旅途的片刻，<br>成为<span>珍藏的一页。</span></h1><p>几张照片，一点心情。<br>把走过的地方，装进属于你的旅行手帐。</p><div class="actions"><button class="primary large" :disabled="busy" @click="input?.click()">{{busy?'正在处理照片…':'选择照片，开始制作'}} ↗</button><button @click="openEditor()">先看看编辑器 →</button></div><small>无需登录 · 照片本地处理 · 免费保存图片</small></div><div class="hero-art"><div class="paper"><div class="mini-label">THE WEEKEND JOURNAL</div><h2>去山野，找自己。</h2><div class="landscape"><i></i><b></b><span>☀</span></div><p>慢一点，风景就在身边。</p><em>GOOD DAYS / 2026</em></div><span class="floating">✳</span></div></section><section class="collection"><div class="section-head"><div class="eyebrow">MADE FOR YOUR MEMORIES</div><h2>从喜欢的风格开始</h2></div><div class="cards"><button v-for="(t,i) in themes" :key="t.name" class="template-card" @click="openEditor(i)"><div class="cover" :style="{background:t.color,color:t.ink}"><small>{{t.tag}} / JOURNAL</small><h3>{{t.name}}</h3><div class="sample-grid"><i></i><i></i><i></i></div><span>把平凡的一天，认真收藏。</span></div><strong>{{t.name}}</strong><span>1–6 张照片 · 竖版手帐 ↗</span></button></div></section></main>
<main v-else-if="page==='templates'" class="collection"><h1>找到你的那一页</h1><p>选择风格，再放进自己的照片。</p><div class="cards"><button v-for="(t,i) in themes" class="template-card" @click="openEditor(i)"><div class="cover" :style="{background:t.color,color:t.ink}"><small>{{t.tag}}</small><h3>{{t.name}}</h3><div class="sample-grid"><i></i><i></i><i></i></div></div><strong>使用这个模板 ↗</strong></button></div></main>
<main v-else-if="page==='drafts'" class="collection"><h1>本机作品</h1><p>仅保存在当前浏览器。清理浏览器数据可能删除草稿，请及时保存成品图片。</p><p v-if="!drafts.length">还没有作品，开始记录第一段旅途吧。</p><div class="cards"><article v-for="d in drafts" class="draft"><h2>{{d.title}}</h2><p>{{new Date(d.updatedAt).toLocaleString()}}</p><button class="primary" @click="resume(d)">继续编辑</button><button @click="remove(d.id)">删除</button></article></div></main>
<main v-else class="editor"><div class="editor-bar"><span>{{status||serverStatus||'照片在当前浏览器处理'}}</span><div><button @click="undo">撤销</button><button @click="redo">重做</button><button class="primary" :disabled="busy" @click="exportImage">{{busy?'处理中…':'保存图片'}} ↓</button></div></div><div class="workspace"><aside><h3>你的照片</h3><button class="upload" @click="input?.click()">＋ 选择 1–6 张照片</button><div class="thumbs"><button v-for="(p,i) in photos" :class="{active:selected===i}" @click="select(i)"><img :src="p" :alt="`照片 ${i+1}`"></button></div><h3>手帐风格</h3><button v-for="(t,i) in themes" class="theme" :class="{active:theme===i}" @click="checkpoint();theme=i;changed()">{{t.name}}</button><h3>贴一点心情</h3><div class="stickers"><button v-for="s in ['🌿','✈️','☕','🌼','📍','🤍']" @click="addSticker(s)">{{s}}</button></div><button @click="checkpoint();stickers=[];changed()">清除贴纸</button></aside><div class="stage"><canvas ref="canvas" aria-label="手帐预览"></canvas></div><aside><h3>写下这一刻</h3><label>标题<input v-model="title" maxlength="20" @focus="checkpoint" @input="editText"></label><label>日期<input v-model="date" type="date" @focus="checkpoint" @input="editText"></label><label>心情<textarea v-model="note" maxlength="120" rows="4" @focus="checkpoint" @input="editText"></textarea></label><template v-if="photos.length"><h3>照片 {{selected+1}} · 取景</h3><label>填充方式<select v-model="fill" @change="crop"><option value="cover">等比裁剪</option><option value="stretch">完整拉伸（可能变形）</option></select></label><label>缩放<input v-model.number="zoom" type="range" min="1" max="3" step=".05" @change="crop"></label><label>左右<input v-model.number="offsetX" type="range" min="-100" max="100" @change="crop"></label><label>上下<input v-model.number="offsetY" type="range" min="-100" max="100" @change="crop"></label></template><label>导出格式<select v-model="format"><option value="image/jpeg">JPG</option><option value="image/png">PNG</option></select></label><p class="hint">作品自动保存在此浏览器。照片不会上传服务器。</p></aside></div></main>
<div v-if="output" class="overlay" role="dialog" aria-modal="true" aria-label="保存图片"><section><button class="close" @click="closeOutput()">关闭 ×</button><h2>这一页，值得收藏。</h2><img :src="output" alt="生成的手帐图片"><a class="primary" :href="output" :download="`TravelDiary-${date}.${format==='image/png'?'png':'jpg'}`">下载图片 ↓</a><p>图片已生成。如浏览器不支持下载，可长按图片保存。</p></section></div>
<footer v-if="page!=='editor'">TravelDiary · 记录旅途，也记录生活。<span>照片本地处理 / 无需登录</span></footer>
</template>
